                U.remove(best_u)
                # move its neighbors from U to W
                for w in adj[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                coloring[v] = color
            # next color
            color += 1
            # remove S from uncolored
            uncolored -= S
