    # Detect adjacency matrix
    is_matrix = False
    if len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list and degree
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = adj[i]
            nbrs = [j for j in range(n) if row[j] == 1]
            neighbors.append(nbrs)
        degree = [len(nbrs) for nbrs in neighbors]
    else:
        neighbors = [list(nbrs) for nbrs in adj]
        degree = [len(nbrs) for nbrs in neighbors]

    # Helper: Welsh-Powell greedy coloring
    def welsh_powell(order=None):
        colors = [-1] * n
        if order is None:
            order = sorted(range(n), key=lambda x: (-degree[x], x))
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if colors[u] != -1:
                    used[colors[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            colors[v] = c
        return colors

    # Initial coloring
    colors = welsh_powell()
    k = max(colors) + 1 if n > 0 else 0

    # Try to improve with Kempe chain swaps
    improved = True
    while improved and k > 1:
        improved = False
        # Build color classes
        color_classes = [[] for _ in range(k)]
        for v in range(n):
            color_classes[colors[v]].append(v)
        # Target the last color class
        target_color = k - 1
        target_vertices = color_classes[target_color][:]
        random.shuffle(target_vertices)
        for v in target_vertices:
            # Try direct reassignment to a lower color
            moved = False
            for c in range(target_color):
                conflict = False
                for u in neighbors[v]:
                    if colors[u] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[v] = c
                    color_classes[target_color].remove(v)
                    color_classes[c].append(v)
                    moved = True
                    improved = True
                    break
            if moved:
                continue
            # Try Kempe chain swap for each lower color
            for c in range(target_color):
                # BFS to find the Kempe chain component of v for colors (target_color, c)
                from collections import deque
                visited = [False] * n
                queue = deque([v])
                visited[v] = True
                component = []
                while queue:
                    node = queue.popleft()
                    component.append(node)
                    for u in neighbors[node]:
                        if not visited[u] and (colors[u] == target_color or colors[u] == c):
                            visited[u] = True
                            queue.append(u)
                # Check if any neighbor of the component has color c
                has_c_neighbor = False
                for node in component:
                    for u in neighbors[node]:
                        if colors[u] == c:
                            has_c_neighbor = True
                            break
                    if has_c_neighbor:
                        break
                if not has_c_neighbor:
                    # Swap colors in the component
                    for node in component:
                        if colors[node] == target_color:
                            colors[node] = c
                        else:
                            colors[node] = target_color
                    # Update color classes
                    color_classes[target_color] = [x for x in color_classes[target_color] if x not in component]
                    color_classes[c] = [x for x in color_classes[c] if x not in component]
                    for node in component:
                        if colors[node] == target_color:
                            color_classes[target_color].append(node)
                        else:
                            color_classes[c].append(node)
                    improved = True
                    break  # break from c loop, restart while
            if improved:
                break  # break from v loop, restart while
        if improved:
            # Recompute k
            k = max(colors) + 1
            # Rebuild color classes for next iteration
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[colors[v]].append(v)
        else:
            break

    # Final Welsh-Powell on the current ordering to polish
    colors = welsh_powell()
    return colors

