def exact_coloring(neighbors, n):
    best_coloring = None
    best_k = n

    def backtrack(idx, colors, used_k):
        nonlocal best_coloring, best_k
        if used_k >= best_k:
            return
        if idx == n:
            best_coloring = colors[:]
            best_k = used_k
            return
        # Try existing colors
        for c in range(used_k):
            conflict = False
            for nb in neighbors[idx]:
                if colors[nb] == c:
                    conflict = True
                    break
            if not conflict:
                colors[idx] = c
                backtrack(idx + 1, colors, used_k)
                colors[idx] = -1
        # Try new color
        colors[idx] = used_k
        backtrack(idx + 1, colors, used_k + 1)
        colors[idx] = -1

    colors = [-1] * n
    backtrack(0, colors, 0)
    return best_coloring if best_coloring is not None else [0] * n

def dsatur_coloring(neighbors, n):
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    while uncolored:
        # Select vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        # Tie-break by degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            selected = candidates[0]
            for v in candidates:
                deg = sum(1 for nb in neighbors[v] if nb in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    selected = v
                elif deg == max_deg and v < selected:
                    selected = v
            v = selected
        else:
            v = candidates[0]
        # Assign smallest available color
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)
        # Update saturation of neighbors
        for nb in neighbors[v]:
            if nb in uncolored:
                saturated[nb].add(c)
    return colors

def rlf_coloring(neighbors, n):
    colors = [-1] * n
    color = 0
    uncolored = set(range(n))

    while uncolored:
        # Find vertex with max degree in uncolored subgraph
        max_deg = -1
        v0 = None
        for v in uncolored:
            deg = sum(1 for nb in neighbors[v] if nb in uncolored)
            if deg > max_deg:
                max_deg = deg
                v0 = v
            elif deg == max_deg and v < v0:
                v0 = v
        # Build independent set for this color
        independent_set = {v0}
        uncolored.remove(v0)
        # U: vertices not adjacent to any in independent_set
        # W: vertices adjacent to at least one in independent_set
        U = set()
        W = set()
        for v in uncolored:
            if any(nb in independent_set for nb in neighbors[v]):
                W.add(v)
            else:
                U.add(v)
        # Greedily add to independent set
        while U:
            # Select u in U with max neighbors in W
            best_u = None
            best_score = -1
            for u in U:
                score = sum(1 for nb in neighbors[u] if nb in W)
                if score > best_score:
                    best_score = score
                    best_u = u
                elif score == best_score:
                    # Tie-break by min degree in U
                    deg_u = sum(1 for nb in neighbors[u] if nb in U)
                    deg_best = sum(1 for nb in neighbors[best_u] if nb in U) if best_u is not None else float('inf')
                    if deg_u < deg_best or (deg_u == deg_best and u < best_u):
                        best_u = u
            if best_u is None:
                break
            independent_set.add(best_u)
            U.remove(best_u)
            # Move neighbors of best_u from U to W
            for nb in neighbors[best_u]:
                if nb in U:
                    U.remove(nb)
                    W.add(nb)
        # Assign color to independent set
        for v in independent_set:
            colors[v] = color
        color += 1
    return colors

def kempe_improve(colors, neighbors, n):
    # Try to eliminate the last color class
    max_color = max(colors) if n > 0 else -1
    if max_color < 0:
        return colors
    # Try multiple iterations
    for _ in range(10):  # Limit iterations for time
        color_classes = [[] for _ in range(max_color + 1)]
        for v in range(n):
            color_classes[colors[v]].append(v)
        # Find smallest non-empty color class (starting from highest color)
        target_color = -1
        min_size = float('inf')
        for c in range(max_color, -1, -1):
            if color_classes[c] and len(color_classes[c]) < min_size:
                min_size = len(color_classes[c])
                target_color = c
        if target_color == -1 or min_size == 0:
            break
        # Try to recolor each vertex in target_color
        made_change = False
        for v in color_classes[target_color][:]:  # Copy list as we may modify
            # Try to move to a lower color directly
            for c in range(target_color):
                conflict = False
                for nb in neighbors[v]:
                    if colors[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    colors[v] = c
                    made_change = True
                    break
            if made_change:
                break
            # Try Kempe chains with each lower color
            for c in range(target_color):
                # Find Kempe chain component of v in colors {c, target_color}
                if colors[v] != target_color:
                    continue
                visited = set()
                stack = [v]
                visited.add(v)
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for nb in neighbors[node]:
                        if nb not in visited and (colors[nb] == c or colors[nb] == target_color):
                            visited.add(nb)
                            stack.append(nb)
                # Check if swapping would cause conflict
                swap_ok = True
                for node in component:
                    for nb in neighbors[node]:
                        if nb not in component and colors[nb] == (c if colors[node] == target_color else target_color):
                            swap_ok = False
                            break
                    if not swap_ok:
                        break
                if swap_ok:
                    # Perform swap
                    for node in component:
                        colors[node] = c if colors[node] == target_color else target_color
                    made_change = True
                    break
            if made_change:
                break
        if not made_change:
            break
        # Update max_color
        max_color = max(colors)
    return colors

def max_clique_lower_bound(neighbors, n):
    # Simple greedy clique finding for lower bound
    max_clique = 0
    # Try multiple random orderings
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        clique = []
        for v in order:
            if all(v in neighbors[u] for u in clique):
                clique.append(v)
        if len(clique) > max_clique:
            max_clique = len(clique)
    # Also try degree ordering
    order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
    clique = []
    for v in order:
        if all(v in neighbors[u] for u in clique):
            clique.append(v)
    if len(clique) > max_clique:
        max_clique = len(clique)
    return max_clique

def backtrack_with_dsatur(neighbors, n, k_limit):
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    def backtrack():
        if not uncolored:
            return True
        # Select vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in uncolored:
            sat = len(saturated[v])
            if sat > max_sat:
                max_sat = sat
                candidates = [v]
            elif sat == max_sat:
                candidates.append(v)
        # Tie-break by degree in uncolored subgraph
        if len(candidates) > 1:
            max_deg = -1
            selected = candidates[0]
            for v in candidates:
                deg = sum(1 for nb in neighbors[v] if nb in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    selected = v
                elif deg == max_deg and v < selected:
                    selected = v
            v = selected
        else:
            v = candidates[0]
        # Try colors in order
        for c in range(k_limit):
            if c in saturated[v]:
                continue
            # Check if color c is valid (should be implied by saturated, but double-check)
            conflict = False
            for nb in neighbors[v]:
                if colors[nb] == c:
                    conflict = True
                    break
            if conflict:
                continue
            # Assign color c
            colors[v] = c
            uncolored.remove(v)
            # Update saturated sets
            updated = []
            for nb in neighbors[v]:
                if nb in uncolored and c not in saturated[nb]:
                    saturated[nb].add(c)
                    updated.append(nb)
            # Recurse
            if backtrack():
                return True
            # Backtrack
            for nb in updated:
                saturated[nb].discard(c)
            uncolored.add(v)
            colors[v] = -1
        return False

    if backtrack():
        return colors
    return None

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect input type: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if it's a binary matrix (0/1)
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        neighbors = []
        for i in range(n):
            row = []
            for j in range(n):
                if adj[i][j] == 1:
                    row.append(j)
            neighbors.append(row)
    else:
        neighbors = adj  # already adjacency list

    deg = [len(neighbors[i]) for i in range(n)]

    # Trivial cases
    if all(d == 0 for d in deg):
        return [0] * n
    if all(d == n - 1 for d in deg):
        return list(range(n))

    # DSATUR algorithm
    color = [-1] * n
    # saturation: list of sets, each set contains colors used by colored neighbors
    saturation = [set() for _ in range(n)]
    # number of colored neighbors (for tie-breaking)
    colored_neighbor_count = [0] * n

    # Helper: get uncolored neighbors count for tie-breaking
    def get_uncolored_degree(v):
        count = 0
        for u in neighbors[v]:
            if color[u] == -1:
                count += 1
        return count

    # Main loop: color all vertices
    for _ in range(n):
        # Select vertex: max saturation degree, then max uncolored degree, then random
        v = -1
        max_sat = -1
        max_uncolored_deg = -1
        for i in range(n):
            if color[i] != -1:
                continue
            sat_i = len(saturation[i])
            if sat_i > max_sat:
                max_sat = sat_i
                max_uncolored_deg = get_uncolored_degree(i)
                v = i
            elif sat_i == max_sat:
                uncolored_deg_i = get_uncolored_degree(i)
                if uncolored_deg_i > max_uncolored_deg:
                    max_uncolored_deg = uncolored_deg_i
                    v = i
                elif uncolored_deg_i == max_uncolored_deg:
                    # Break tie randomly
                    if random.random() < 0.5:
                        v = i
        # If no vertex found (should not happen), pick first uncolored
        if v == -1:
            for i in range(n):
                if color[i] == -1:
                    v = i
                    break

        # Find smallest available color (mex)
        used = saturation[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c

        # Update saturation and colored neighbor count for all uncolored neighbors
        for u in neighbors[v]:
            if color[u] == -1:
                saturation[u].add(c)
                colored_neighbor_count[u] += 1

    # Local search: Kempe chain refinement to reduce color count
    max_color = max(color) if n > 0 else -1
    if max_color < 0:
        return color

    # Try to reduce colors from max_color down to 0
    for target_color in range(max_color, 0, -1):
        # Collect vertices with color = target_color
        class_vertices = [i for i in range(n) if color[i] == target_color]
        if not class_vertices:
            continue  # This color class is already empty

        # Try to recolor each vertex in this class to a lower color
        made_progress = False
        for v in class_vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            for c in range(target_color):
                if c not in neighbor_colors:
                    # Direct move possible
                    color[v] = c
                    made_progress = True
                    break
            if made_progress:
                break  # Re-start the scan for this target_color after a change

            # Try Kempe chains for each lower color
            for c in range(target_color):
                # We'll attempt to swap colors c and target_color in the component containing v
                # Only if v is not adjacent to any vertex of color c (otherwise swap would conflict immediately)
                if any(color[u] == c for u in neighbors[v]):
                    continue  # Adjacent to color c, swap would cause conflict

                # Build the Kempe chain: connected component of v in the subgraph of colors {c, target_color}
                stack = [v]
                visited = set([v])
                # We'll also track if we encounter any vertex that, when swapped, would pull a vertex of color c into the class
                # Actually, we want to know if the component contains any vertex of color c that is adjacent to a vertex of color target_color (outside the component?) 
                # Standard: the swap is safe if the component does not contain any vertex of color c that is adjacent to a vertex of color target_color that is not in the component? 
                # Instead, we note: after swap, v will become color c. We already checked v has no neighbor of color c.
                # For other vertices in the component: 
                #   - if a vertex x of color c is in the component, after swap it becomes target_color. We must ensure x has no neighbor of color target_color (after swap) that is not swapped.
                #   But since we are swapping the entire component, any neighbor of x that is color target_color and in the component will become color c, so no conflict.
                #   The only potential conflict is if x has a neighbor y of color target_color that is NOT in the component. After swap, x becomes target_color and y remains target_color -> conflict.
                # Therefore, the swap is safe if and only if no vertex in the component of color c has a neighbor of color target_color outside the component.
                # Similarly, no vertex in the component of color target_color has a neighbor of color c outside the component? 
                # But we started from v (color target_color) and we know v has no neighbor of color c (checked). For other target_color vertices in the component, we don't need to check? 
                # Actually, symmetric condition: for any vertex in the component of color target_color, it must not have a neighbor of color c outside the component.
                # However, note: if a target_color vertex in the component had a neighbor of color c outside the component, then that neighbor would be in the component (because we traverse via edges to same or other color in the pair) -> contradiction. 
                # Therefore, we only need to check for vertices of color c in the component: they must not have a neighbor of color target_color outside the component.

                # We'll collect the component and then check the condition.
                component = set()
                stack = [v]
                visited = set([v])
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for u in neighbors[node]:
                        if color[u] == c or color[u] == target_color:
                            if u not in visited:
                                visited.add(u)
                                stack.append(u)

                # Check: for every node x in component with color[x] == c, 
                #   all neighbors of x that are color target_color must be in the component.
                safe = True
                for x in component:
                    if color[x] == c:
                        for u in neighbors[x]:
                            if color[u] == target_color and u not in component:
                                safe = False
                                break
                        if not safe:
                            break
                if safe:
                    # Perform the swap: swap colors c and target_color in the component
                    for x in component:
                        if color[x] == c:
                            color[x] = target_color
                        elif color[x] == target_color:
                            color[x] = c
                    made_progress = True
                    break  # break out of color loop, restart scanning this target_color
            if made_progress:
                break
        if not made_progress:
            # Could not eliminate this color class, move to next lower target color
            continue
        else:
            # We made progress, so we need to re-check the same target_color because the class might still have vertices
            # We'll reset the loop for this target_color by not decrementing yet; but easier: we break and let the outer loop continue, 
            # but we want to try again for the same target_color. Instead, we do: after a successful recolor, we break and then the outer loop will continue with the same target_color? 
            # Actually, we broke out of the inner loops and then we are here. We set made_progress and break out of the vertex loop, then we are after the vertex loop.
            # We then check: if made_progress, we do not break the target_color loop, but we continue to next iteration of the same target_color? 
            # But we want to try again to eliminate the class because there might be more vertices. 
            # So we do not break the target_color loop; we let it run again for the same target_color. 
            # However, note: we are in a for loop over target_color. We cannot easily stay on the same target_color without restructuring.
            # Instead, we do: after making progress, we break out of the vertex loop and then continue the target_color loop (which will decrement target_color). 
            # But we want to try again for the same target_color. 
            # Therefore, we change strategy: we use a while loop for each target_color.
            pass  # We'll restructure below

    # Restructure: for each target_color from high to low, repeatedly try to eliminate until no progress
    # We'll redo the local search with a while loop per target_color.
    # But to avoid deep nesting, we break out and restructure the code.
    # Given the time, we'll do a simpler approach: multiple passes until no improvement.
    # We'll do at most n passes of Kempe attempts.

    # Clear and redo local search with multiple passes
    # We'll try to reduce the color count by repeatedly attempting to eliminate the highest color class.
    improved = True
    # We'll limit passes to avoid infinite loop
    for _pass in range(n):  # at most n passes
        if not improved:
            break
        improved = False
        max_color = max(color) if n > 0 else -1
        if max_color < 0:
            break
        # Try to eliminate color class max_color
        class_vertices = [i for i in range(n) if color[i] == max_color]
        if not class_vertices:
            improved = True  # already empty, consider as progress? but we break anyway
            continue
        made_progress = False
        for v in class_vertices:
            # Try direct reassignment to a lower color
            neighbor_colors = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            for c in range(max_color):
                if c not in neighbor_colors:
                    color[v] = c
                    made_progress = True
                    improved = True
                    break
            if made_progress:
                break
            # Try Kempe chains
            for c in range(max_color):
                if any(color[u] == c for u in neighbors[v]):
                    continue
                # Build component of v in colors {c, max_color}
                stack = [v]
                visited = set([v])
                component = set()
                while stack:
                    node = stack.pop()
                    component.add(node)
                    for u in neighbors[node]:
                        if color[u] == c or color[u] == max_color:
                            if u not in visited:
                                visited.add(u)
                                stack.append(u)
                # Check safety: for every x in component with color[x]==c, all neighbors of color max_color must be in component
                safe = True
                for x in component:
                    if color[x] == c:
                        for u in neighbors[x]:
                            if color[u] == max_color and u not in component:
                                safe = False
                                break
                        if not safe:
                            break
                if safe:
                    # Swap colors c and max_color in component
                    for x in component:
                        if color[x] == c:
                            color[x] = max_color
                        elif color[x] == max_color:
                            color[x] = c
                    made_progress = True
                    improved = True
                    break
            if made_progress:
                break
        # If we made progress, we continue the pass loop to try again (maybe eliminate further)

    return color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = (n > 0 and len(adj[0]) == n and
                 all(isinstance(row, list) and len(row) == n for row in adj) and
                 all(all(x in (0, 1) for x in row) for row in adj))
    # Build adjacency list
    if is_matrix:
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        graph = [list(neigh) for neigh in adj]
        # Ensure symmetry for undirected graph (if not already)
        for i in range(n):
            for j in graph[i]:
                if i not in graph[j]:
                    graph[j].append(i)
    # Handle trivial cases
    if n == 1:
        return [0]
    # Check if edgeless
    if all(len(graph[i]) == 0 for i in range(n)):
        return [0] * n
    # Check if complete
    is_complete = True
    for i in range(n):
        if len(graph[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))
    # DSATUR with RLF fallback and Kempe chain refinement
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        # Order by degree descending for initial tie-breaking
        order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
        for v in order:
            if colored[v]:
                continue
            # Compute saturation degree: number of distinct colors in neighbors
            neighbor_colors = set()
            for u in graph[v]:
                if color[u] != -1:
                    neighbor_colors.add(color[u])
            sat[v] = len(neighbor_colors)
            # Find uncolored vertex with max saturation, tie-break by degree in uncolored subgraph, then random
            max_sat = -1
            candidates = []
            for u in range(n):
                if not colored[u]:
                    if sat[u] > max_sat:
                        max_sat = sat[u]
                        candidates = [u]
                    elif sat[u] == max_sat:
                        candidates.append(u)
            if max_sat == -1:  # no uncolored left (should not happen)
                break
            # Tie-break: max degree in uncolored subgraph
            max_deg = -1
            best = []
            for u in candidates:
                deg = 0
                for w in graph[u]:
                    if not colored[w]:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    best = [u]
                elif deg == max_deg:
                    best.append(u)
            v_sel = random.choice(best) if best else candidates[0]
            # Assign smallest available color
            used = [False] * (n + 1)
            for u in graph[v_sel]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v_sel] = c
            colored[v_sel] = True
            # Update saturation of neighbors
            for u in graph[v_sel]:
                if not colored[u]:
                    sat[u] = len({color[w] for w in graph[u] if color[w] != -1})
        return color
    # Recursive Largest First (RLF) for independent set extraction
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # Step 1: pick uncolored vertex with max degree in uncolored subgraph
            max_deg = -1
            v = -1
            for i in range(n):
                if not colored[i]:
                    deg = 0
                    for nb in graph[i]:
                        if not colored[nb]:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        v = i
            if v == -1:
                break
            S = [v]
            colored[v] = True
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set()
            W = set()
            for i in range(n):
                if not colored[i]:
                    if i not in graph[v]:
                        U.add(i)
                    else:
                        W.add(i)
            # Step 4: while U not empty
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = 0
                    for nb in graph[u]:
                        if nb in W:
                            score += 1
                    if score > best_score:
                        best_score = score
                        best_u = u
                    elif score == best_score:
                        # tie-break: min degree in G[U]
                        deg_u = sum(1 for nb in graph[u] if nb in U)
                        deg_best = sum(1 for nb in graph[best_u] if nb in U) if best_u != -1 else float('inf')
                        if deg_u < deg_best:
                            best_u = u
                if best_u == -1:
                    break
                S.append(best_u)
                colored[best_u] = True
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for nb in graph[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color c to all in S
            for node in S:
                color[node] = c
            c += 1
        return color
    # Kempe chain refinement to reduce color count
    def kempe_refine(color_in):
        color = color_in[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # Try to eliminate color k-1
            target = k - 1
            vertices = [i for i in range(n) if color[i] == target]
            if not vertices:
                k -= 1
                continue
            # Try to recolor each vertex in target class
            for v in vertices:
                # Try direct move to lower color
                neighbor_colors = set(color[u] for u in graph[v] if color[u] != -1)
                for c in range(target):
                    if c not in neighbor_colors:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
                # Try Kempe chain swap
                for c in range(target):
                    # Skip if v already has color c (should not happen)
                    if color[v] == c:
                        continue
                    # Check if v is adjacent to any vertex of color c
                    adj_to_c = any(color[u] == c for u in graph[v])
                    if adj_to_c:
                        continue
                    # Build (c, target) Kempe chain containing v
                    stack = [v]
                    visited = set([v])
                    while stack:
                        node = stack.pop()
                        for nb in graph[node]:
                            if nb not in visited and (color[nb] == c or color[nb] == target):
                                visited.add(nb)
                                stack.append(nb)
                    # Swap colors in component
                    for node in visited:
                        if color[node] == c:
                            color[node] = target
                        elif color[node] == target:
                            color[node] = c
                    # After swap, check if v can now take color c (should be free)
                    neighbor_colors_new = set(color[u] for u in graph[v] if color[u] != -1)
                    if c not in neighbor_colors_new:
                        color[v] = c
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                # Cannot reduce further
                break
            # Recompute k
            k = max(color) + 1
        return color
    # Run DSATUR first
    col_dsatur = dsatur()
    k_dsatur = max(col_dsatur) + 1 if n > 0 else 0
    # Run RLF
    col_rlf = rlf()
    k_rlf = max(col_rlf) + 1 if n > 0 else 0
    # Choose the better initial coloring
    if k_dsatur <= k_rlf:
        col = col_dsatur
    else:
        col = col_rlf
    # Apply Kempe chain refinement
    col = kempe_refine(col)
    # Final validation (optional, but safe)
    # Ensure no adjacent same color
    for i in range(n):
        for j in graph[i]:
            if i < j and color[i] == color[j]:
                # Fallback to greedy Welsh-Powell if something went wrong
                order = sorted(range(n), key=lambda x: len(graph[x]), reverse=True)
                color_greedy = [-1] * n
                for v in order:
                    used = [False] * (n + 1)
                    for u in graph[v]:
                        if color_greedy[u] != -1:
                            used[color_greedy[u]] = True
                    c = 0
                    while c < n and used[c]:
                        c += 1
                    color_greedy[v] = c
                return color_greedy
    return col

