def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine input type: adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x == 0 or x == 1 for x in row) for row in adj):
            is_matrix = True

    # Build neighbor list and degree array
    if is_matrix:
        neighbors = []
        deg = [0] * n
        for i in range(n):
            row_neighbors = []
            for j in range(n):
                if adj[i][j] == 1:
                    row_neighbors.append(j)
                    deg[i] += 1
            neighbors.append(row_neighbors)
    else:
        neighbors = [list(lst) for lst in adj]
        deg = [len(lst) for lst in neighbors]

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (by degree descending)
    def welsh_powell_order():
        return sorted(range(n), key=lambda x: deg[x], reverse=True)

    # Helper: smallest-last ordering (Matula-Beck)
    def smallest_last_order():
        if n == 0:
            return []
        current_deg = deg[:]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for v in range(n):
            d = current_deg[v]
            if d < n:
                buckets[d].append(v)
        min_d = 0
        for _ in range(n):
            while min_d < n and not buckets[min_d]:
                min_d += 1
            if min_d >= n:
                break
            v = buckets[min_d].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d_u = current_deg[u]
                    current_deg[u] = d_u - 1
                    if d_u - 1 < n:
                        buckets[d_u - 1].append(u)
                    if d_u - 1 < min_d:
                        min_d = d_u - 1
        return order[::-1]

    # Helper: DSATUR heuristic
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        colored = [False] * n
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if not colored[i]:
                    if sat[i] > max_sat or (sat[i] == max_sat and deg[i] > max_deg) or \
                       (sat[i] == max_sat and deg[i] == max_deg and (v == -1 or random.random() < 0.5)):
                        max_sat = sat[i]
                        max_deg = deg[i]
                        v = i
            if v == -1:
                break  # should not happen
            # Find smallest available color
            used = [False] * n
            for u in neighbors[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            colored[v] = True
            # Update saturation of uncolored neighbors
            for u in neighbors[v]:
                if not colored[u]:
                    sat[u] += 1
        return color

    # Helper: RLF (Recursive Largest First) heuristic
    def rlf():
        color = [-1] * n
        colored = [False] * n
        c = 0
        while not all(colored):
            # Build set of uncolored vertices R
            R = [i for i in range(n) if not colored[i]]
            if not R:
                break
            # Compute degrees in subgraph induced by R
            deg_R = [0] * n
            for v in R:
                for u in neighbors[v]:
                    if not colored[u]:
                        deg_R[v] += 1
            # Select first vertex: max degree in R
            v1 = max(R, key=lambda x: deg_R[x])
            S = [v1]
            colored[v1] = True
            # Partition R \ {v1} into U (not adjacent to S) and W (adjacent to S)
            U = []
            W = []
            for v in R:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in neighbors[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.append(v)
                else:
                    U.append(v)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max neighbors in W
                u_star = -1
                max_nw = -1
                min_deg_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    nw = 0
                    for w in W:
                        if w in neighbors[u]:
                            nw += 1
                    # Tie-break: min degree in U (current deg_R in U subgraph)
                    deg_u_U = 0
                    for w in U:
                        if w != u and w in neighbors[u]:
                            deg_u_U += 1
                    if nw > max_nw or (nw == max_nw and deg_u_U < min_deg_U) or \
                       (nw == max_nw and deg_u_U == min_deg_U and (u_star == -1 or random.random() < 0.5)):
                        max_nw = nw
                        min_deg_U = deg_u_U
                        u_star = u
                if u_star == -1:
                    break  # should not happen if U not empty
                S.append(u_star)
                colored[u_star] = True
                U.remove(u_star)
                # Move neighbors of u_star in U to W
                for w in list(U):
                    if w in neighbors[u_star]:
                        U.remove(w)
                        W.append(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            c += 1
        return color

    # Generate initial colorings from multiple heuristics
    colorings = []
    # Welsh-Powell
    order_wp = welsh_powell_order()
    colorings.append(greedy_color(order_wp))
    # Smallest-last
    order_sl = smallest_last_order()
    colorings.append(greedy_color(order_sl))
    # DSATUR
    colorings.append(dsatur())
    # RLF
    colorings.append(rlf())

    # Select the coloring with the fewest colors
    best_color = None
    best_k = float('inf')
    for col in colorings:
        k = max(col) + 1 if col else 0
        if k < best_k:
            best_k = k
            best_color = col

    # Local search: Kempe chain refinement to eliminate color classes
    def kempe_refine(coloring):
        nonlocal best_k
        k = max(coloring) + 1 if coloring else 0
        if k <= 1:
            return coloring
        improved = True
        while improved and k > 1:
            improved = False
            # Identify vertices in the last color class (k-1)
            last_color = k - 1
            verts_last = [v for v in range(n) if coloring[v] == last_color]
            if not verts_last:
                k -= 1
                improved = True
                continue
            # Try to recolor each vertex in last color class
            for v in verts_last:
                # Try direct move to a lower color
                moved = False
                for c in range(last_color):
                    conflict = False
                    for u in neighbors[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        moved = True
                        improved = True
                        break
                if moved:
                    continue
                # Try Kempe chain swap with each lower color
                for c in range(last_color):
                    # Build the (c, last_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for u in neighbors[node]:
                            if not visited[u] and (coloring[u] == c or coloring[u] == last_color):
                                visited[u] = True
                                queue.append(u)
                    # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                    has_c_neighbor = False
                    for u in component:
                        for w in neighbors[u]:
                            if coloring[w] == c and w in component:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            break
                    if not has_c_neighbor:
                        # Perform swap: c <-> last_color in component
                        for u in component:
                            if coloring[u] == c:
                                coloring[u] = last_color
                            elif coloring[u] == last_color:
                                coloring[u] = c
                        improved = True
                        moved = True
                        break
                if moved:
                    break
            # After attempting to recolor, check if last color class is empty
            if not any(coloring[v] == last_color for v in range(n)):
                k -= 1
                improved = True
        return coloring

    # Apply Kempe refinement to the best coloring
    refined = kempe_refine(best_color[:])
    # Verify correctness (debug, can be removed for speed)
    # for u in range(n):
    #     for v in neighbors[u]:
    #         if refined[u] == refined[v]:
    #             raise ValueError("Invalid coloring")
    return refined

