            v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored]), random.random()))
            # Find smallest available color
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
        return color

    # Try RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Step 1: pick vertex with max degree in G[uncolored]
            v = max(uncolored, key=lambda x: (len([y for y in neighbors[x] if y in uncolored]), random.random()))
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = {u for u in uncolored if u != v and all(u not in neighbors[w] for w in S)}
            W = {u for u in uncolored if u != v and any(u in neighbors[w] for w in S)}
            # While U not empty
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: (len([y for y in neighbors[x] if y in W]), -len([y for y in neighbors[x] if y in U]), random.random()))
                S.add(u)
                U.remove(u)
                # Move neighbors of u that are in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return color

    # Try Welsh-Powell (degree ordering)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (-len(neighbors[x]), random.random()))
        color = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Try smallest-last ordering (degeneracy ordering)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use bucket sort for efficiency, but n is small
        for _ in range(n):
            # Find vertex with min degree among non-removed
            v = -1
            min_deg = float('inf')
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    deg[u] -= 1
        # Color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return color

    # Run all algorithms and pick the best (fewest colors)
    best_coloring = None
    best_colors = float('inf')

    for func in [dsatur, rlf, welsh_powell, smallest_last]:
        try:
            col = func()
            # Validate coloring
            valid = True
            for u in range(n):
                for v in neighbors[u]:
                    if u < v and color[u] == color[v]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                num_colors = max(col) + 1 if col else 0
                if num_colors < best_colors:
                    best_colors = num_colors
                    best_coloring = col
        except:
            continue

    # Fallback to Welsh-Powell if all failed (should not happen)
    if best_coloring is None:
        best_coloring = welsh_powell()

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []

    n = len(adj)

    # Detect if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    if is_matrix:
        neighbors = [[j for j in range(n) if adj[i][j] == 1] for i in range(n)]
    else:
        # Treat as adjacency list
        neighbors = [list(lst) for lst in adj]
        # Ensure symmetry and no self-loops
        for i in range(n):
            neighbors[i] = [j for j in neighbors[i] if j != i and 0 <= j < n]
            for j in neighbors[i]:
                if i not in neighbors[j]:
                    neighbors[j].append(i)

    # Remove duplicates and sort for consistency
    for i in range(n):
        neighbors[i] = sorted(set(neighbors[i]))

    # Handle trivial cases
    if n == 1:
        return [0]

    # Check if edgeless
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Check if complete graph
    is_complete = True
    for i in range(n):
        if len(neighbors[i]) != n - 1:
            is_complete = False
            break
    if is_complete:
        return list(range(n))

    # DSATUR implementation
    def dsatur():
        colors = [-1] * n
        # Precompute neighbor sets for fast lookup
        neighbor_sets = [set(neighbors[i]) for i in range(n)]
        # Saturation sets: colors used by colored neighbors
        saturation = [set() for _ in range(n)]
        # Degrees in uncolored subgraph (initially full degree)
        degree = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))

        # Helper to get saturation degree
        def sat_degree(v):
            return len(saturation[v])

        # Helper to get degree in uncolored subgraph
        def uncolored_degree(v):
            # Count uncolored neighbors
            return sum(1 for u in neighbors[v] if u in uncolored)

        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            candidates = []
            max_sat = -1
            for v in uncolored:
                sd = sat_degree(v)
                if sd > max_sat:
                    max_sat = sd
                    candidates = [v]
                elif sd == max_sat:
                    candidates.append(v)

            # Tie-break by max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg = -1
                new_candidates = []
                for v in candidates:
                    ud = uncolored_degree(v)
                    if ud > max_deg:
                        max_deg = ud
                        new_candidates = [v]
                    elif ud == max_deg:
                        new_candidates.append(v)
                candidates = new_candidates

            # Final tie-break: random
            v = random.choice(candidates)

            # Find smallest available color
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            colors[v] = c
            uncolored.remove(v)

            # Update saturation for uncolored neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u].add(c)

        return colors

    # RLF implementation
    def rlf():
        colors = [-1] * n
        neighbor_sets = [set(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        color = 0

        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v_start = -1
            for v in uncolored:
                deg = sum(1 for u in neighbors[v] if u in uncolored)
                if deg > max_deg:
                    max_deg = deg
                    v_start = v

            if v_start == -1:  # Should not happen
                break

            S = {v_start}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set(uncolored - S - neighbor_sets[v_start])
            W = set(uncolored) - S - U

            while U:
                # Select u in U with max neighbors in W
                best_u = -1
                max_w_neighbors = -1
                min_u_deg_in_U = float('inf')

                for u in U:
                    w_neighbors = sum(1 for w in neighbor_sets[u] if w in W)
                    # Tie-break: min degree in U
                    u_deg_in_U = sum(1 for nb in neighbor_sets[u] if nb in U)

                    if w_neighbors > max_w_neighbors:
                        max_w_neighbors = w_neighbors
                        min_u_deg_in_U = u_deg_in_U
                        best_u = u
                    elif w_neighbors == max_w_neighbors:
                        if u_deg_in_U < min_u_deg_in_U:
                            min_u_deg_in_U = u_deg_in_U
                            best_u = u

                if best_u == -1:
                    break  # No valid vertex, should not happen

                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                to_move = set()
                for u in U:
                    if best_u in neighbor_sets[u]:
                        to_move.add(u)
                U -= to_move
                W |= to_move

            # Assign color to all in S
            for v in S:
                colors[v] = color
                uncolored.remove(v)

            color += 1

        return colors

    # Welsh-Powell implementation
    def welsh_powell():
        # Order by degree descending
        order = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        colors = [-1] * n

        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return colors

    # Smallest-Last ordering implementation
    def smallest_last():
        # Compute core numbers and removal order
        degree = [len(neighbors[i]) for i in range(n)]
        # Buckets for degrees
        max_deg = max(degree) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree[v]
            if d <= max_deg:
                bins[d].append(v)

        # Pointer to current non-empty bin
        pos = 0
        order = []
        # Copy of degree for modification
        curr_degree = degree[:]
        # Set of removed vertices
        removed = [False] * n

        for _ in range(n):
            # Find non-empty bin
            while pos <= max_deg and not bins[pos]:
                pos += 1
            if pos > max_deg:
                break  # Should not happen

            v = bins[pos].pop()
            if removed[v]:
                # Find another in this bin
                while bins[pos] and removed[bins[pos][-1]]:
                    bins[pos].pop()
                if not bins[pos]:
                    pos += 1
                    while pos <= max_deg and not bins[pos]:
                        pos += 1
                    if pos > max_deg:
                        break
                    v = bins[pos].pop()
                else:
                    v = bins[pos].pop()

            order.append(v)
            removed[v] = True
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = curr_degree[u]
                    # Remove u from its current bin
                    if d <= max_deg and u in bins[d]:
                        bins[d].remove(u)
                    curr_degree[u] -= 1
                    d_new = curr_degree[u]
                    if d_new <= max_deg:
                        bins[d_new].append(u)

        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c

        return colors

    # Kempe chain refinement to reduce colors
    def kempe_refine(colors):
        # Determine current number of colors
        max_color = max(colors) if n > 0 else -1
        if max_color < 0:
            return colors

        # Build color classes
        color_classes = [[] for _ in range(max_color + 1)]
        for v in range(n):
            c = colors[v]
            if c != -1:
                color_classes[c].append(v)

        # Try to eliminate color classes from highest down
        changed = True
        while changed and max_color >= 0:
            changed = False
            # Find smallest non-empty color class (by index, but we try high colors first for reduction)
            # We try to reduce the highest color first
            for c in range(max_color, -1, -1):
                if not color_classes[c]:
                    continue
                # Try to recolor each vertex in class c to a lower color
                for v in color_classes[c][:]:  # iterate over copy
                    # Try direct reassignment to lower colors
                    neighbor_colors = set()
                    for u in neighbors[v]:
                        if colors[u] != -1:
                            neighbor_colors.add(colors[u])

                    for c_low in range(c):
                        if c_low not in neighbor_colors:
                            # Direct move possible
                            colors[v] = c_low
                            color_classes[c].remove(v)
                            color_classes[c_low].append(v)
                            changed = True
                            break
                    if changed:
                        break

                    # Try Kempe chains
                    for c_low in range(c):
                        # Check if v can be swapped via Kempe chain (c, c_low)
                        # Only consider if c_low is not in neighborhood (otherwise direct move would work)
                        if c_low in neighbor_colors:
                            continue

                        # Build the Kempe chain component containing v for colors c and c_low
                        # We'll do BFS/DFS on the subgraph induced by colors c and c_low
                        from collections import deque
                        visited = set()
                        queue = deque([v])
                        visited.add(v)
                        component = set()
                        # We want to see if we can swap c and c_low in this component
                        # without causing conflict. Actually, we check if swapping frees color c for v.
                        # Standard: if the component does not contain any neighbor of v colored c_low,
                        # then swapping will move v to c_low and not introduce conflict.
                        has_c_low_neighbor = False
                        while queue:
                            node = queue.popleft()
                            component.add(node)
                            for u in neighbors[node]:
                                if colors[u] == c or colors[u] == c_low:
                                    if u not in visited:
                                        visited.add(u)
                                        queue.append(u)
                                    # Check if this neighbor is colored c_low and adjacent to v
                                    if u == v and colors[u] == c_low:  # self not possible
                                        pass
                                    if u in neighbors[v] and colors[u] == c_low:
                                        has_c_low_neighbor = True

                        # If no neighbor of v in the component is colored c_low, swapping is safe
                        if not has_c_low_neighbor:
                            # Perform swap: c <-> c_low in component
                            for node in component:
                                if colors[node] == c:
                                    colors[node] = c_low
                                elif colors[node] == c_low:
                                    colors[node] = c
                            # Update color classes
                            for node in component:
                                old_c = c if colors[node] == c_low else c_low
                                new_c = colors[node]
                                color_classes[old_c].remove(node)
                                color_classes[new_c].append(node)
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break

            # Update max_color if highest color class is empty
            while max_color >= 0 and not color_classes[max_color]:
                max_color -= 1

        return colors

    # Try multiple algorithms and select the best
    best_colors = None
    best_num_colors = float('inf')

    # List of algorithms to try
    algorithms = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last)
    ]

    for name, algo in algorithms:
        try:
            cols = algo()
            # Validate coloring
            valid = True
            for i in range(n):
                for j in neighbors[i]:
                    if i < j and cols[i] == cols[j]:
                        valid = False
                        break
                if not valid:
                    break
            if valid:
                num_colors = len(set(cols))
                if num_colors < best_num_colors:
                    best_num_colors = num_colors
                    best_colors = cols[:]
        except Exception:
            continue

    # Fallback: greedy in random order
    if best_colors is None:
        order = list(range(n))
        random.shuffle(order)
        colors = [-1] * n
        for v in order:
            used = set()
            for u in neighbors[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            c = 0
            while c in used:
                c += 1
            colors[v] = c
        best_colors = colors

    # Apply Kempe refinement to try to reduce further
    try:
        refined = kempe_refine(best_colors)
        # Validate refined coloring
        valid = True
        for i in range(n):
            for j in neighbors[i]:
                if i < j and refined[i] == refined[j]:
                    valid = False
                    break
            if not valid:
                break
        if valid:
            num_colors_refined = len(set(refined))
            if num_colors_refined < best_num_colors:
                best_colors = refined
    except Exception:
        pass

    return best_colors
